export type CuaPermissionKind = "accessibility" | "screen_recording";

export interface OpenCuaPermissionOnboardingOptions {
  /** Opaque id generated by the Renderer for this call; closing this permission surface cancels only this participant. */
  operationId?: string;
  initialPermission?: CuaPermissionKind;
  /** Permissions still missing after confirming the latest state; main opens the corresponding settings page for each and waits for the app to return. */
  requiredPermissions?: CuaPermissionKind[];
}

export interface CuaAccessibilitySettingsResult {
  success: boolean;
  canceled?: boolean;
  /** Main-level onboarding session id; concurrent windows with the same Helper identity share this id. */
  sessionId?: string;
  /** True only after every staged settings page has observed a ZCode window return. */
  returnedFromSettings?: boolean;
  /**
   * Multiple windows may join the same main onboarding session. Each independent renderer/host has exactly one call return true and is responsible for
   * restarting that host's Helper; repeated calls from the same renderer return false. Do not choose only one window globally, because each window
   * has its own host/Helper and each process started before authorization must resume independently.
   * undefined is a legacy shape from old main processes; treat it as a single-window owner.
   */
  restartHelperAfterReturn?: boolean;
  error?: string;
}

/**
 * Drag prewarming result (renderer-visible shape).
 *
 * Note that `helperBundleFingerprint` is intentionally **not declared here**: it is synchronous TOCTOU evidence cached in main-process memory
 * (compared before dragstart to prove "bytes have not changed since signature verification"). Exposing it to the renderer over IPC is useless and expands the attack surface.
 * Main has a separate `PrepareCuaHelperPermissionDragMainResult` carrying the field; the IPC handler explicitly strips it before returning.
 */
export interface PrepareCuaHelperPermissionDragResult {
  success: boolean;
  error?: string;
  helperAppPath?: string;
  helperDisplayName?: string;
  helperBundleId?: string;
}
